import { photoRef, SourceAdapter } from '../sources/types';
import { Collection, DEFAULT_PLAY, PhotoRef, PlaySettings, SamplesSource } from '../store/types';
import manifest from './manifest.json';

// The photos that come with the app: themed collections of openly licensed
// pictures, packaged under samples/<theme>/ (full size) and
// samples/<theme>/thumb/ (grid size). The manifest is generated by
// scripts/samples/build.mjs, which also records each photo's licence.

export interface SamplePhoto {
  file: string;
  title: string;
  /** "Photo: Jane Doe" / "Claude Monet, 1906". */
  by: string;
  license: string;
  licenseUrl?: string;
  /** Where the original lives (its Commons or museum page). */
  source: string;
  width: number;
  height: number;
}

export interface SampleCollection {
  id: string;
  name: string;
  play: Partial<PlaySettings>;
  photos: SamplePhoto[];
}

export const SAMPLE_COLLECTIONS = (manifest as { collections: SampleCollection[] }).collections;

export const SAMPLES_ID = 'samples';
export const samplesSource: SamplesSource = { id: SAMPLES_ID, kind: 'samples', name: 'Included photos' };

/** Collection ids of the included collections, so they can be restored. */
export const sampleCollectionId = (theme: string) => `sample-${theme}`;

function credit(p: SamplePhoto): string {
  return /public domain|cc0/i.test(p.license) ? p.by : `${p.by} · ${p.license}`;
}

function ref(theme: string, p: SamplePhoto): PhotoRef {
  return photoRef(SAMPLES_ID, `${theme}/${p.file}`, p.title, {
    width: p.width,
    height: p.height,
    caption: p.title,
    credit: credit(p),
  });
}

/** The included collections, ready to add to the store. */
export function sampleCollections(): Collection[] {
  const now = Date.now();
  return SAMPLE_COLLECTIONS.map((c, i) => ({
    id: sampleCollectionId(c.id),
    name: c.name,
    photos: c.photos.map((p) => ref(c.id, p)),
    createdAt: now + i,
    updatedAt: now + i,
    play: { ...DEFAULT_PLAY, ...c.play },
  }));
}

export function samplesAdapter(): SourceAdapter {
  return {
    source: samplesSource,
    async list(folderKey) {
      if (folderKey === null) {
        return {
          key: null,
          title: samplesSource.name,
          entries: SAMPLE_COLLECTIONS.map((c) => ({ type: 'folder' as const, key: c.id, name: c.name })),
        };
      }
      const c = SAMPLE_COLLECTIONS.find((x) => x.id === folderKey);
      if (!c) throw new Error('No such collection');
      return { key: c.id, title: c.name, entries: c.photos.map((p) => ({ type: 'photo' as const, ref: ref(c.id, p) })) };
    },
    // Files inside the app package, already upright and screen-sized; no
    // EXIF to read (so no readHead) and ready-made thumbnails.
    thumbUrl: (r) => Promise.resolve(`samples/${r.key.replace(/\/([^/]+)$/, '/thumb/$1')}`),
    imageUrl: (r) => Promise.resolve(`samples/${r.key}`),
  };
}
